#!/usr/bin/env python3
# Writes egress_vectors.txt: the egress-control gate of stock RNS 1.5.2,
# computed by its own BackboneInterface._dp_ec_evaluate, for the test
# the_gate_matches_the_reference_evaluation in src/interface_writer.rs.
#
#   <venv>/bin/python -I egress_vectors.py > egress_vectors.txt
#
# The venv needs rns 1.5.2. Each case is one connection looked at once a
# DP_EC_INTERVAL; each look gives the bytes queued and not yet sent and the
# bytes sent so far, and the reference's tx_stalled after it. No case lets
# DP_EC_DEAD_TIME pass without progress: in the port that teardown is the
# socket's write limit, not the gate, and the script fails if a case would
# reach it.

import sys

import RNS
from RNS.Interfaces.BackboneInterface import BackboneInterface as B

assert RNS.__version__ == "1.5.2", RNS.__version__

KIB = 1024
MID = B.DP_EC_MID_WM


class Buffer:
    def __init__(self): self.pending, self._tx_sent = 0, 0
    def __len__(self): return self.pending
    @property
    def sendable(self): return self.pending


class Connection:
    def __init__(self):
        self.transmit_buffer = Buffer()
        self._dp_ec_prev_sent = 0
        self._dp_ec_zero_ticks = 0
        self._dp_ec_last_drain = 0.0
        self.tx_stalled = False
        self.socket = None
    def receive(self, data):
        raise SystemExit("a case reached DP_EC_DEAD_TIME; keep cases short of it")


def run(name, looks):
    # looks: [(pending, sent_total), ...], one DP_EC_INTERVAL apart.
    c = Connection()
    steps = []
    for i, (pending, sent) in enumerate(looks):
        c.transmit_buffer.pending, c.transmit_buffer._tx_sent = pending, sent
        torn_down = B._dp_ec_evaluate(c, (i + 1) * B.DP_EC_INTERVAL)
        assert not torn_down
        steps.append(f"{pending},{sent} -> {c.tx_stalled}")
    print(f"{name}: " + "; ".join(steps))


def drain(start_pending, start_sent, per_look, added_per_look, count):
    # A backlog drained by per_look bytes a look while added_per_look arrive.
    looks, pending, sent = [], start_pending, start_sent
    for _ in range(count):
        sent += per_look
        pending = max(0, pending - per_look + added_per_look)
        looks.append((pending, sent))
    return looks


print("# Generated by egress_vectors.py from stock RNS", RNS.__version__,
      "BackboneInterface._dp_ec_evaluate; do not edit.")
print(f"# DP_EC_INTERVAL={B.DP_EC_INTERVAL} DP_EC_MID_WM={B.DP_EC_MID_WM} DP_EC_STALL_TICKS={B.DP_EC_STALL_TICKS}"
      f" DP_EC_MAX_ETA={B.DP_EC_MAX_ETA} DP_EC_RELEASE_ETA={B.DP_EC_RELEASE_ETA} DP_EC_DEAD_TIME={B.DP_EC_DEAD_TIME}")

run("idle", [(0, 0), (0, 0), (0, 0)])
run("small_backlog_never_gated", [(100 * KIB, 0)] * 6)
run("at_mid_wm_never_gated", [(MID, 0)] * 6)
run("just_over_mid_wm_no_drain", [(MID + 1, 0)] * 5)
run("no_drain_then_progress", [(200 * KIB, 0), (200 * KIB, 0), (150 * KIB, 50 * KIB), (150 * KIB, 50 * KIB), (150 * KIB, 50 * KIB), (150 * KIB, 50 * KIB)])
run("slow_drain_gated", drain(1024 * KIB, 0, 50_000, 50_000, 4))
run("slow_drain_then_recovers", drain(1024 * KIB, 0, 50_000, 50_000, 3) + drain(1024 * KIB, 150_000, 400 * KIB, 0, 4))
run("hysteresis_holds_between_release_and_max", drain(1024 * KIB, 0, 50_000, 50_000, 2) + [(800 * KIB, 200_000), (800 * KIB, 330_000), (800 * KIB, 460_000)])
run("eta_exactly_max_not_gated", [(1000 * KIB, 100 * KIB), (1000 * KIB, 200 * KIB)])
run("gated_then_backlog_falls_to_mid_wm", drain(1024 * KIB, 0, 50_000, 50_000, 2) + [(MID, 100_000), (MID, 100_000)])
run("gated_then_emptied", drain(1024 * KIB, 0, 50_000, 50_000, 2) + [(0, 1_200_000)])
run("no_drain_gates_then_progress_releases", [(300 * KIB, 0)] * 3 + [(20 * KIB, 280 * KIB), (20 * KIB, 300 * KIB)])
run("murph_burst_drained_in_two_seconds", [(557 * KIB, 0), (300 * KIB, 257 * KIB), (40 * KIB, 517 * KIB), (0, 557 * KIB)])
